import { useState } from 'react'

import { TodoAlreadyCompletedError } from '../../application/TodoAlreadyCompletedError'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

export type CompleteTodoState = {
  readonly completed: boolean
  readonly pending: boolean
  readonly error: string | null
  readonly complete: () => void
}

export const useCompleteTodo = (id: string): CompleteTodoState => {
  const { completeTodo } = useTodosUseCases()
  const [completed, setCompleted] = useState(false)
  const [pending, setPending] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const complete = () => {
    setPending(true)
    setError(null)
    completeTodo.execute(id).then(
      () => {
        setCompleted(true)
        setPending(false)
      },
      (failure: unknown) => {
        setPending(false)
        setError(
          failure instanceof TodoAlreadyCompletedError
            ? 'This todo is already completed.'
            : 'The todo could not be completed.',
        )
      },
    )
  }

  return { completed, pending, error, complete }
}
